UPDATE agent_definitions SET default_config = jsonb_set(..., '{workflow,steps,check_rerender_mode,config,condition}', to_jsonb(<live condition> || ' OR input_data.spec.reason == ''template_changed''')) WHERE type='page-rerender' AND <verbatim pre-image guard>;

UPDATE agent_definitions SET default_config = jsonb_set(jsonb_set(..., '{...,create_rerender,config,query}', to_jsonb('INSERT INTO site_work_items ... SELECT p.site_id, ..., ''page_rerender'', ..., ''page-rerender'', ''triaged'', ..., jsonb_build_object(''reason'',''template_changed'',''page_id'',p.id::text,''page_name'',p.name,''domain'',s.domain) FROM page_components pc JOIN pages p ... WHERE pc.component_id = $1::uuid AND NOT EXISTS (<open template_changed item for this page>)')), '{...,params}', '["fix_result.component_id"]') WHERE type='component-template-fixer' AND <pre-image guard>;

DO $$ ... RAISE EXCEPTION unless: condition contains template_changed AND all three prior reasons; fixer query contains template_changed+page_rerender; params name fix_result.component_id $$;
